1	const basePremiumsByType: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25 };
2	
3	const BLOCK_SIZE = 3;
4	const BLOCK_PREMIUM = 60;
5	
6	const basePremiumForItem = (item: { type: string }): number => basePremiumsByType[item.type];
7	
8	const isBlockOfAlikeComponents = (items: { type: string }[]): boolean =>
9	  items.length === BLOCK_SIZE && items.every((item) => item.type === "rune");
10	
11	export const basePremium = (items: { type: string }[]): number => {
12	  if (isBlockOfAlikeComponents(items)) {
13	    return BLOCK_PREMIUM;
14	  }
15	  return items.reduce((sum, item) => sum + basePremiumForItem(item), 0);
16	};
